declare(strict_types=1);
$actor=(int)require_user()['user_id'];$seller=($orderMode??'buyer')==='seller';$title=$seller?'คำสั่งซื้อเข้าร้าน':'คำสั่งซื้อของคุณ';$shop=$seller?own_shop($actor):null;
$rows=$seller?($shop?query('SELECT o.*,s.shop_name,u.full_name AS buyer_name FROM orders o JOIN shops s ON s.shop_id=o.shop_id JOIN users u ON u.user_id=o.buyer_user_id WHERE s.owner_user_id=? ORDER BY o.order_id DESC LIMIT 100',[$actor])->fetchAll():[]):query('SELECT o.*,s.shop_name FROM orders o JOIN shops s ON s.shop_id=o.shop_id WHERE o.buyer_user_id=? ORDER BY o.order_id DESC LIMIT 100',[$actor])->fetchAll();
require ROOT.'/app/templates/header.php';if($seller)require ROOT.'/app/templates/seller-nav.php'; ?>
<section class="page-heading"><div><h1><?=$seller?'Orders for your shop.':'Your orders.'?></h1><p class="muted"><?=$seller?'จัดการสถานะตามขั้นตอนการรับสินค้า':'ติดตามเสื้อผ้าตัวโปรดของคุณได้ที่นี่'?></p></div></section>
<?php if(!$rows): ?><section class="empty"><h2>ยังไม่มีคำสั่งซื้อ</h2><p>เมื่อมีคำสั่งซื้อ รายละเอียดจะแสดงที่นี่</p><a class="button secondary" href="<?=h(url('products.php'))?>">Explore</a></section><?php else: ?><div class="table-wrap"><table><thead><tr><th>คำสั่งซื้อ</th><th><?=$seller?'ผู้ซื้อ':'ร้าน'?></th><th>วิธีรับ</th><th>ยอดรวม</th><th>สถานะ</th><th>รายละเอียด</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td>#<?=$row['order_id']?><small><?=h($row['created_at'])?> UTC</small></td><td><?=h($seller?$row['buyer_name']:$row['shop_name'])?></td><td><?=$row['fulfillment_method']==='pickup'?'นัดรับ':'จัดส่ง'?></td><td><?=money($row['total_amount'])?></td><td><span class="status <?=h($row['status'])?>"><?=h(STATUS_LABELS[$row['status']]??$row['status'])?></span></td><td><a class="underlined" href="<?=h(url('order.php?id='.$row['order_id']))?>">ดูคำสั่งซื้อ</a></td></tr><?php endforeach; ?></tbody></table></div><p class="field-help">แสดงล่าสุดไม่เกิน 100 คำสั่งซื้อ ข้อมูลเวลาอ้างอิง UTC</p><?php endif; ?>
